const initialState = {
  dogs: [],
  temperaments: [],
  error: {},
  dogDetail: {},
  currentPage: 1,
  allDogs: [],
  filteredDogs: [],
};

function rootReducer(state = initialState, action) {
  switch (action.type) {
    case "GET_DOGS":
      return {
        ...state,
        dogs: action.payload,
        allDogs: action.payload,
      };
    case "GET_TEMPERAMENTS":
      return {
        ...state,
        temperaments: action.payload,
      };

    case "GET_DETAIL":
      return {
        ...state,
        dogDetail: action.payload,
      };

    case "GET_BY_NAME":
      return {
        ...state,
        dogs: action.payload,
      };

      case 'FILTER_BY':
      if (action.payload === "DB") {
        let data = state.dogs.filter((item) => typeof item.id === "string")
        if(data.length <= 0){
          return {
            ...state,
            filtered: 'NO_BREEDS'
          }
        } else
        return {
          ...state,
          filtered: data
        };
      } else {
        return {
          ...state,
          filtered: state.dogs.filter((item) => typeof item.id === "number"),
        };
      }

    case "FILTER_TEMPERAMENT":
      console.log("payload:", action.payload);
      const allDogs = state.allDogs;
      console.log("allDogs:", allDogs);
      const temperamentsFiltered = allDogs.filter((dog) =>
        // dog.temperament &&
        dog.temperaments.map((temp) => temp).includes(action.payload)
      );

      console.log("filteredDogs:", temperamentsFiltered);
      return {
        ...state,
        dogs: temperamentsFiltered,
      };

    case "ORDER_BY":
      if (action.payload === "A-Z") {
        return {
          ...state,
          currentPage: 1,
          filtered: [...state.filtered].sort((prev, next) => {
            if (prev.name > next.name) return 1;
            if (prev.name < next.name) return -1;
            return 0;
          }),
        };
      }

      if (action.payload === "Z-A") {
        return {
          ...state,
          currentPage: 1,
          filtered: [...state.filtered].sort((prev, next) => {
            if (prev.name > next.name) return -1;
            if (prev.name < next.name) return 1;
            return 0;
          }),
        };
      }

      if (action.payload === "desc") {
        return {
          ...state,
          currentPage: 1,
          filtered: [...state.filtered].sort(
            (prev, next) => prev.weight.slice(0, 2) - next.weight.slice(0, 2)
          ),
        };
      }

      if (action.payload === "asc") {
        return {
          ...state,
          currentPage: 1,
          filtered: [...state.filtered].sort(
            (prev, next) => next.weight.slice(0, 2) - prev.weight.slice(0, 2)
          ),
        };
      } else {
        return { ...state, filtered: state.dogs };
      };

    case "LOADING":
      return {
        ...state,
        loading: true,
      };
    case "CLEAN":
      return {
        ...state,
        dogDetail: [],
      };

    default:
      return state;
  }
}
console.log(initialState);

export default rootReducer;
